package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.*;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.golems.*;
import thaumcraft.alchemy.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class GolemProbe {
    public static final BlockPos Q=new BlockPos(200,205,8);static final UUID OWNER=UUID.fromString("6be7c45a-6764-4c37-b8d3-d719a6fdc001");static ServerPlayer p;static GolemBuilder builder;static int ticks;static boolean done;
    public static void giveComponents(ServerPlayer p,GolemDesign d){p.getInventory().clearContent();int i=0;for(var e:d.components().entrySet()){var item=BuiltInRegistries.ITEM.getValue(Identifier.parse(e.getKey()));int count=e.getValue();while(count>0){int n=Math.min(count,new ItemStack(item).getMaxStackSize());p.getInventory().setItem(i++,new ItemStack(item,n));count-=n;}}}
    public static void rules(ServerPlayer p,GolemBuilder b){p.setPos(Vec3Helper.x(b),b.getBlockPos().getY()+1,b.getBlockPos().getZ()+.5);knowledge(p);b.draft=new GolemDesign(3,1,1,3);giveComponents(p,b.draft);var old=p.getInventory().getItem(0).copy();p.getInventory().setItem(1,ItemStack.EMPTY);check(!b.start(p)&&ItemStack.matches(old,p.getInventory().getItem(0)),"Missing components partially charged");giveComponents(p,b.draft);var state=thaumcraft.research.ResearchService.state(p);thaumcraft.research.KnowledgeStore.write(p,state.stage("MINDBIOTHAUMIC",0));check(!b.start(p)&&!b.working(),"Missing part research allowed craft");thaumcraft.research.KnowledgeStore.write(p,state);check(b.start(p)&&b.working()&&p.getInventory().isEmpty(),"Press failed exact payment");check(!b.start(p)&&!b.edit(p,0),"Paid design can be edited or charged twice");check(!b.insert("motus",Direction.DOWN,false)&&!b.insert("machina",Direction.UP,false),"Press accepts wrong essentia or face");for(int i=0;i<3;i++)check(b.insert("machina",Direction.DOWN,false),"Press refused valid essence");check(b.remaining()==b.total()-3,"Essence not debited exactly");
        for(var floor:BlockPos.betweenClosed(b.getBlockPos().offset(4,-1,-1),b.getBlockPos().offset(6,-1,1)))p.level().setBlockAndUpdate(floor,Blocks.STONE.defaultBlockState());var g=new WorkerGolem(GolemContent.GOLEM.get(),p.level());g.configure(p,b.draft,b.getBlockPos().east(5),7);g.cargo.setItem(0,new ItemStack(Items.DIAMOND,17));g.setMode(2);g.setCustomName(Component.literal("Persistent porter"));g.setHealth(7);p.level().addFreshEntity(g);
        var seal=seal(p,SealKind.FILL,b.getBlockPos().east(7));seal.channel=7;seal.priority=4;seal.radius=6;seal.filter=new ItemStack(Items.DIAMOND);seal.setChanged();var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());g.saveWithoutId(out);var copy=new WorkerGolem(GolemContent.GOLEM.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.ownerId().equals(p.getUUID())&&copy.channel()==7&&copy.design().equals(b.draft)&&copy.cargo.getItem(0).getCount()==17&&copy.getHealth()==7,"Golem snapshot lost state");check(seal.matches(new ItemStack(Items.DIAMOND))&&!seal.matches(new ItemStack(Items.EMERALD)),"Exact filter failed");seal.blacklist=true;check(!seal.matches(new ItemStack(Items.DIAMOND))&&seal.matches(new ItemStack(Items.EMERALD)),"Blacklist failed");seal.blacklist=false;seal.setChanged();Thaumcraft.LOGGER.info("GOLEM_RULES_OK: atomic costs, research, busy locks, essentia faces and worker snapshot");}
    public static SealEntity seal(ServerPlayer p,SealKind kind,BlockPos at){var l=p.level();l.setBlockAndUpdate(at.below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(at,GolemContent.SEALS.get(kind).get().defaultBlockState());var s=(SealEntity)l.getBlockEntity(at);s.claimOwner(p);return s;}
    @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("golem-write")&&!mode.equals("golem-read"))return;var l=e.getServer().overworld();l.setChunkForced(Q.getX()>>4,Q.getZ()>>4,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"GolemProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);p.setPos(Q.getX()+.5,Q.getY()+1,Q.getZ()+.5);if(mode.equals("golem-write")){l.setBlockAndUpdate(Q,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(Q,GolemContent.BUILDER.get().defaultBlockState());builder=(GolemBuilder)l.getBlockEntity(Q);rules(p,builder);}else{builder=(GolemBuilder)l.getBlockEntity(Q);check(builder!=null&&builder.working()&&builder.remaining()==builder.total()-3&&builder.output.isEmpty(),"Paid press job did not survive restart");var s=(SealEntity)l.getBlockEntity(Q.east(7));check(s!=null&&s.channel==7&&s.priority==4&&s.radius==6&&s.filter.is(Items.DIAMOND)&&s.owner().equals(OWNER),"Seal configuration did not survive restart");}}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("golem-write")&&!mode.equals("golem-read")||done||++ticks<40)return;if(mode.equals("golem-write")){done=true;Thaumcraft.LOGGER.info("GOLEM_WRITE_OK: paid unfinished press, named porter and configured seal saved");e.server().halt(false);return;}var l=e.server().overworld();var workers=l.getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(Q).inflate(16));check(workers.stream().anyMatch(g->g.ownerId().equals(OWNER)&&g.channel()==7&&g.mode()==2&&g.getCustomName().getString().equals("Persistent porter")&&g.cargo.getItem(0).getCount()==17&&g.getHealth()==7),"Native saved worker lost cargo/owner/design/health");while(builder.working())check(builder.insert("machina",Direction.DOWN,false),"Resumed press refused essence");check(builder.output.getItem(0).get(GolemContent.DESIGN.get()).equals(new GolemDesign(3,1,1,3)),"Resumed press output mismatch");check(!builder.insert("machina",Direction.DOWN,false),"Finished press charged extra essence");done=true;Thaumcraft.LOGGER.info("GOLEM_RESTART_OK: exact job completion, entity cargo/owner/health and seal configuration");e.server().halt(false);}
    static final class Vec3Helper{static double x(GolemBuilder b){return b.getBlockPos().getX()+.5;}}
}
